q:
select count(*) 
from "order" 
where "order_dow" = 0 and "order_hour_of_day" between 6 and 12;

select distinct product_name, user_id from product Natural Join `order-product`
    join `order` on `order`.order_id  = `order-product`.order_id
    order by user_id desc;

r:
select product_name, count(distinct user_id) as num_users from product Natural Join `order-product`
    join `order` on `order`.order_id  = `order-product`.order_id
    group by product_name having count(distinct user_id) >= 200 order by num_users desc;

q:
SELECT DISTINCT A.product_id, A.product_name, B.product_id, B.product_name
FROM product AS A, product AS B
WHERE A.product_name LIKE  '%Chips Ahoy!%' AND A.product_name LIKE '%Chewy%' AND B.product_name LIKE '%Chips Ahoy!%' AND B.product_name LIKE '%Chewy%' AND A.product_name = B.product_name AND A.product_id < B.product_id;

r:
SELECT DISTINCT A.product_id, A.product_name, B.product_id, B.product_name
FROM product AS A, product AS B
WHERE A.product_name LIKE  '%Chips Ahoy!%' AND A.product_name LIKE '%Chewy%' AND B.product_name LIKE '%Chips Ahoy!%' AND B.product_name LIKE '%Chewy%' AND A.product_id < B.product_id;

SELECT product.product_id, product.product_name, "order-product".order_id, "order-product".add_to_cart_order
FROM product JOIN "order-product" ON product.product_id="order-product".product_id
WHERE "order-product".add_to_cart_order = (SELECT MAX(add_to_cart_order) FROM "order-product");

q:
SELECT 'affiliation:' || ' ' || (Select a.title FROM (SELECT agent_id, city from agent ) ag, (SELECT agent_id, title FROM (SELECT aff_id, agent_id from affiliationrel) NATURAL JOIN (SELECT title, aff_id from affiliation)) a, (SELECT * FROM (SELECT * FROM teamrel tr NATURAL JOIN (SELECT team_id, name FROM team) t WHERE tr.team_id == t.team_id) tname, (SELECT name, team_id from mission) m WHERE m.team_id == tname.team_id AND m.name == 'Media Blanket') miss WHERE miss.agent_id == a.agent_id AND ag.agent_id == miss.agent_id) as aff_city
INTERSECT
SELECT 'city:' || ' ' || (Select ag.city FROM (SELECT agent_id, city from agent ) ag, (SELECT agent_id, title FROM (SELECT aff_id, agent_id from affiliationrel) NATURAL JOIN (SELECT title, aff_id from affiliation)) a, (SELECT * FROM (SELECT * FROM teamrel tr NATURAL JOIN (SELECT team_id, name FROM team) t WHERE tr.team_id == t.team_id) tname, (SELECT name, team_id from mission) m WHERE m.team_id == tname.team_id AND m.name == 'Media BlanketX') miss WHERE miss.agent_id == a.agent_id AND ag.agent_id == miss.agent_id) as aff_city;
